@pytest.mark.parametrize("checkpoint", ["classifier", "regressor"]) @pytest.mark.parametrize("precision", ["fp32", "bf16", "autocast_bf16"]) @pytest.mark.parametrize( ("nodes", "block_size"), [(64, 1), (64, 17), (64, 256), (257, 64), (257, 128)], ) def test_actual_checkpoint_gnn_and_frozen_cache( checkpoint: str, precision: str, nodes: int, block_size: int ) -> None: root = os.environ.get("SDM_RELATIONAL_CHECKPOINT_ROOT") if root is None: pytest.skip("Set SDM_RELATIONAL_CHECKPOINT_ROOT for offline weights") device = torch.device(os.environ.get("SDM_GNN_REVIEW_DEVICE", "cpu")) if device.type == "cuda" and not torch.cuda.is_available(): pytest.skip("CUDA review requested without a CUDA device") state = torch.load( Path(root) / f"{checkpoint}.pt", map_location="cpu", weights_only=True ) gnn_state = { key.removeprefix("gnn."): value for key, value in state.items() if key.startswith("gnn.") } model = InvariantGNN(512).eval() model.load_state_dict(gnn_state) model.to(device) if precision == "bf16": model.bfloat16() candidate = BlockedInvariantGNN(model, block_size=block_size) degrees = torch.tensor([0, 1, 3, 17]).repeat((nodes + 3) // 4)[:nodes] graph = graph_from_degrees(degrees) graph = replace( graph, row=graph.row.to(device), col=graph.col.to(device), colptr=graph.colptr.to(device), edge_type=graph.edge_type.to(device), ) x = torch.arange(nodes * 512).reshape(nodes, 512).float().mul(0.01).sin() if precision == "bf16": x = x.bfloat16() x = x.to(device) readout_index = torch.tensor([nodes - 3, 0, 13, 0, 39], device=device) if device.type == "cuda": # CPU historical screen remains unchanged; CUDA covers every target. readout_index = torch.cat( [torch.arange(nodes - 2, device=device), readout_index] ) kwargs = { "graph": graph, "readout_table": "readout", "readout_index": readout_index, "num_hops": 2, } tolerance = ( {"rtol": 1e-5, "atol": 2e-6} if precision == "fp32" else {"rtol": 2e-2, "atol": 2e-2} ) baseline_cache, candidate_cache = Cache(), Cache() with ( torch.inference_mode(), torch.autocast( device.type, dtype=torch.bfloat16, enabled=precision == "autocast_bf16", ), ): expected = model( x, **kwargs, cache=baseline_cache, generator=torch.Generator(device=device).manual_seed(1729), ) actual = candidate( x, **kwargs, cache=candidate_cache, generator=torch.Generator(device=device).manual_seed(1729), ) comparisons = [("fit", actual.clone(), expected.clone())] torch.testing.assert_close( candidate_cache["edge_type_emb"], baseline_cache["edge_type_emb"], rtol=0, atol=0, ) baseline_cache.freeze() candidate_cache.freeze() expected = model(x.flip(0), **kwargs, cache=baseline_cache) actual = candidate(x.flip(0), **kwargs, cache=candidate_cache) comparisons.append(("frozen_query", actual, expected)) record = { "evidence_kind": ( f"{device.type.upper()} GNN-only, synthetic inputs, actual weights" ), "device": str(device), "gpu_name": torch.cuda.get_device_name(device) if device.type == "cuda" else None, "cuda_version": torch.version.cuda, "allow_tf32": torch.backends.cuda.matmul.allow_tf32, "torch_version": torch.__version__, "checkpoint": checkpoint, "checkpoint_revision": "2bd603d3d8f25f67a7aaa8579908595e20567e22", "checkpoint_sha256": file_sha256(str(Path(root) / f"{checkpoint}.pt")), "adapter_source_sha256": file_sha256( inspect.getfile(BlockedInvariantGNN) ), "test_source_sha256": file_sha256(__file__), "nodes": nodes, "edges": graph.num_edges, "channels": 512, "degree_pattern": [0, 1, 3, 17], "feature_formula": "sin(arange(nodes*512)*0.01)", "edge_rng_seed": 1729, "num_hops": 2, "readout_rows": readout_index.numel(), "block_size": block_size, "precision": precision, "tolerance": tolerance, "comparisons": {}, } for phase, actual, expected in comparisons: difference = (actual.float() - expected.float()).abs() accepted = difference <= ( tolerance["atol"] + tolerance["rtol"] * expected.float().abs() ) record["comparisons"][phase] = { "max_abs_error": float(difference.max()), "mean_abs_error": float(difference.mean()), "mismatched_elements": int((~accepted).sum()), "elements": actual.numel(), "pass": bool(accepted.all()), "bitwise_equal": bool(torch.equal(actual, expected)), } output = os.environ.get("SDM_GNN_REVIEW_OUTPUT") if output is not None: destination = Path(output) destination.mkdir(parents=True, exist_ok=True) prefix = "cuda-" if device.type == "cuda" else "" name = f"{prefix}{checkpoint}-{precision}-n{nodes}-b{block_size}.json" (destination / name).write_text(json.dumps(record, indent=2) + "\n") for _, actual, expected in comparisons: > torch.testing.assert_close(actual, expected, **tolerance) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 5115 / 34304 (14.9%) E Greatest absolute difference: 0.000980764627456665 at index (59, 82) (up to 2e-06 allowed) E Greatest relative difference: 0.15992790460586548 at index (23, 433) (up to 1e-05 allowed)
