nts": int((~accepted).sum()), "elements": actual.numel(), "pass": bool(accepted.all()), "bitwise_equal": bool(torch.equal(actual, expected)), } output = os.environ.get("SDM_GNN_REVIEW_OUTPUT") if output is not None: destination = Path(output) destination.mkdir(parents=True, exist_ok=True) prefix = "cuda-" if device.type == "cuda" else "" name = f"{prefix}{checkpoint}-{precision}-n{nodes}-b{block_size}.json" (destination / name).write_text(json.dumps(record, indent=2) + "\n") for _, actual, expected in comparisons: > torch.testing.assert_close(actual, expected, **tolerance) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 35 / 133120 (0.0%) E Greatest absolute difference: 0.033203125 at index (233, 110) (up to 0.02 allowed) E Greatest relative difference: 2.46875 at index (148, 354) (up to 0.02 allowed)
